struct ExtWorkspaceHandleV1Sink {
mut:
	proxy    ExtWorkspaceHandleV1
	listener ExtWorkspaceHandleV1Listener = NoopExtWorkspaceHandleV1Listener{}
}

fn (mut s ExtWorkspaceHandleV1Sink) on_event(msg &wayland.Message) !bool {
	match msg.opcode {
		0 {
			id := msg.arg_string(0)!
			s.listener.id(s.proxy, id)
		}
		1 {
			name := msg.arg_string(0)!
			s.listener.name(s.proxy, name)
		}
		2 {
			coordinates := msg.arg_array(0)!
			s.listener.coordinates(s.proxy, coordinates)
		}
		3 {
			state := msg.arg_u32(0)!
			s.listener.state(s.proxy, state)
		}
		4 {
			capabilities := msg.arg_u32(0)!
			s.listener.capabilities(s.proxy, capabilities)
		}
		5 {
			s.listener.removed(s.proxy)
		}
		else {
			return false
		}
	}
	return true
}

// set_listener registers the handler that receives ext_workspace_handle_v1 events.
pub fn (proxy &ExtWorkspaceHandleV1) set_listener(listener ExtWorkspaceHandleV1Listener) ! {
	proxy.conn.set_sink(proxy.id, ExtWorkspaceHandleV1Sink{
		proxy:    *proxy
		listener: listener
	})!
}

// Destroys the ext_workspace_handle_v1 object. This request should be made
// either when the client does not want to use the workspace object any more
// or after the remove event to finalize the destruction of the object.
pub fn (proxy &ExtWorkspaceHandleV1) destroy() ! {
	proxy.conn.request(proxy.id, 0, []wayland.ArgValue{})!
	proxy.conn.destroy_object(proxy.id)
}

// Request that this workspace be activated. There is no guarantee the
// workspace will be actually activated, and behaviour may be
// compositor-dependent. For example, activating a workspace may or may not
// deactivate all other workspaces in the same group.
pub fn (proxy &ExtWorkspaceHandleV1) activate() ! {
	proxy.conn.request(proxy.id, 1, []wayland.ArgValue{})!
}

// Request that this workspace be deactivated. There is no guarantee the
// workspace will be actually deactivated.
pub fn (proxy &ExtWorkspaceHandleV1) deactivate() ! {
	proxy.conn.request(proxy.id, 2, []wayland.ArgValue{})!
}

// Requests that this workspace is assigned to the given workspace group.
// There is no guarantee the workspace will be assigned.
pub fn (proxy &ExtWorkspaceHandleV1) assign(workspace_group ExtWorkspaceGroupHandleV1) ! {
	proxy.conn.request(proxy.id, 3, [wayland.ArgValue(wayland.ObjectRef{ id: workspace_group.id })])!
}

// Request that this workspace be removed. There is no guarantee the
// workspace will be actually removed.
pub fn (proxy &ExtWorkspaceHandleV1) remove() ! {
	proxy.conn.request(proxy.id, 4, []wayland.ArgValue{})!
}

