// bind_ext_workspace_manager_v1 binds the ext_workspace_manager_v1 global to a typed proxy.
pub fn bind_ext_workspace_manager_v1(conn &wayland.Connection, global wayland.Global) !ExtWorkspaceManagerV1 {
	version := if global.version < ext_workspace_manager_v1_desc.version {
		global.version
	} else {
		ext_workspace_manager_v1_desc.version
	}
	object := conn.bind_global(global, 'ext_workspace_manager_v1', version, &ext_workspace_manager_v1_desc)!
	return ExtWorkspaceManagerV1{
		Object: object
	}
}
